     1→import { LitElement, html } from "lit";
     2→import { customElement, state } from "lit/decorators.js";
     3→import { ClaudeData } from "../../src/types";
     4→import {
     5→	SharedConversationProcessor,
     6→	SimpleConversation,
     7→	ProcessedPair,
     8→} from "../../src/shared-conversation-processor";
     9→
    10→@customElement("claude-app")
    11→export class ClaudeApp extends LitElement {
    12→	@state() private data: ClaudeData = { rawPairs: [] };
    13→	@state() private conversations: SimpleConversation[] = [];
    14→	@state() private processedPairs: ProcessedPair[] = [];
    15→	@state() private currentView: "conversations" | "raw" | "json" = "conversations";
    16→	@state() private selectedModels: Set<string> = new Set();
    17→
    18→	// Disable shadow DOM to use global Tailwind styles
    19→	createRenderRoot() {
    20→		console.log("createRenderRoot");
    21→		return this;
    22→	}
    23→
    24→	connectedCallback() {
    25→		super.connectedCallback();
    26→		this.data = window.claudeData || { rawPairs: [] };
    27→		this.processData();
    28→	}
    29→
    30→	private processData() {
    31→		const start = performance.now();
    32→
    33→		// Use shared processor for both processed pairs and conversations
    34→		const processor = new SharedConversationProcessor();
    35→
    36→		// Process raw pairs using shared processor
    37→		this.processedPairs = processor.processRawPairs(this.data.rawPairs);
    38→		// Check for include all requests flag from environment or data
    39→		const includeAllRequests = this.data.metadata?.includeAllRequests || false;
    40→		this.conversations = processor.mergeConversations(this.processedPairs, {
    41→			includeShortConversations: includeAllRequests,
    42→		});
    43→
    44→		// Initialize with all models available, but haiku models disabled by default in UI
    45→		const conversationModels = new Set(this.conversations.flatMap((c) => Array.from(c.models)));
    46→		const processedPairModels = new Set(this.processedPairs.map((p) => p.model));
    47→		const rawPairModels = new Set(this.data.rawPairs.map((pair) => pair.request.body?.model || "unknown"));
    48→		const allModels = new Set([...conversationModels, ...processedPairModels, ...rawPairModels]);
    49→
    50→		// Select all models by default (including haiku)
    51→		this.selectedModels = allModels;
    52→		console.log(`Processed data in ${performance.now() - start}ms`);
    53→	}
    54→
    55→	private switchView(view: "conversations" | "raw" | "json") {
    56→		this.currentView = view;
    57→	}
    58→
    59→	private toggleModel(model: string) {
    60→		const newSelectedModels = new Set(this.selectedModels);
    61→		if (newSelectedModels.has(model)) {
    62→			newSelectedModels.delete(model);
    63→		} else {
    64→			newSelectedModels.add(model);
    65→		}
    66→		this.selectedModels = newSelectedModels;
    67→	}
    68→
    69→	private get filteredConversations() {
    70→		return this.conversations.filter((c) => {
    71→			// Show conversation if ANY of its models are selected
    72→			return Array.from(c.models).some((model) => this.selectedModels.has(model));
    73→		});
    74→	}
    75→
    76→	private get filteredProcessedPairs() {
    77→		return this.processedPairs.filter((pair) => this.selectedModels.has(pair.model));
    78→	}
    79→
    80→	private get filteredRawPairs() {
    81→		return this.data.rawPairs.filter((pair) => {
    82→			const model = pair.request.body?.model || "unknown";
    83→			return this.selectedModels.has(model);
    84→		});
    85→	}
    86→
    87→	private get allRawPairs() {
    88→		// Debug view shows ALL raw pairs without any filtering
    89→		return this.data.rawPairs.filter((pair) => pair.response !== null);
    90→	}
    91→
    92→	private get modelCounts() {
    93→		const counts = new Map<string, number>();
    94→		this.conversations.forEach((c) => {
    95→			// Count each model used in conversations
    96→			Array.from(c.models).forEach((model) => {
    97→				counts.set(model, (counts.get(model) || 0) + 1);
    98→			});
    99→		});
   100→		return counts;
   101→	}
   102→
   103→	render() {
   104→		const modelCounts = this.modelCounts;
   105→		const filteredConversations = this.filteredConversations;
   106→
   107→		return html`
   108→			<div class="min-h-screen bg-vs-bg text-vs-text font-mono">
   109→				<div class="max-w-[60em] mx-auto p-4">
   110→					<div class="mb-8">
   111→						<div class="mb-4 text-center">
   112→							<span class="text-vs-function">~ claude-traffic</span>
   113→							<span class="text-vs-muted ml-8">${this.data.timestamp || new Date().toISOString()}</span>
   114→						</div>
   115→
   116→						<div class="mb-8 text-center">
   117→							<span
   118→								@click=${() => this.switchView("conversations")}
   119→								class="cursor-pointer mr-12 ${this.currentView === "conversations"
   120→									? "text-vs-nav-active"
