     3→// Configure marked for safe HTML rendering
     4→marked.setOptions({
     5→	gfm: true, // GitHub Flavored Markdown
     6→	breaks: true, // Convert \n to <br>
     7→});
     8→
     9→/**
    10→ * Escape HTML entities to prevent XSS
    11→ */
    12→function escapeHtml(text: string): string {
    13→	return text
    14→		.replace(/&/g, "&amp;")
    15→		.replace(/</g, "&lt;")
    16→		.replace(/>/g, "&gt;")
    17→		.replace(/"/g, "&quot;")
    18→		.replace(/'/g, "&#39;");
    19→}
    20→
    21→/**
    22→ * Convert markdown text to HTML string with proper escaping
    23→ * @param markdown - The markdown text to convert
    24→ * @returns HTML string
    25→ */
    26→export function markdownToHtml(markdown: string): string {
    27→	if (!markdown) return "";
    28→
    29→	try {
    30→		// First escape any existing HTML entities to prevent XSS
    31→		const escapedMarkdown = escapeHtml(markdown);
    32→		return marked(escapedMarkdown) as string;
    33→	} catch (error) {
    34→		console.warn("Failed to parse markdown:", error);
    35→		// Fallback to plain text with basic line break handling and HTML escaping
    36→		return escapeHtml(markdown).replace(/\n/g, "<br>");
    37→	}
    38→}
